{
  "components": [
    {
      "type": "claim",
      "quote": "Interested parties have the opportunity to submit comments and statements of position within the scope of the consultation and participation procedure.",
      "gist": "Interested parties can provide input during the consultation and participation process."
    },
    {
      "type": "claim",
      "quote": "The sectoral planning procedure is implemented in several stages.",
      "gist": "The sectoral planning procedure consists of multiple stages."
    },
    {
      "type": "entity",
      "quote": "Swissgrid AG",
      "gist": "Swissgrid AG, the national grid operator"
    },
    {
      "type": "claim",
      "quote": "The entity submitting the application (as a rule, national grid operator Swissgrid AG) draws up potential planning zone variants and concludes a cooperation agreement with the involved cantons.",
      "gist": "The applicant (usually Swissgrid AG) creates planning zone options and signs a cooperation agreement with cantons."
    },
    {
      "type": "claim",
      "quote": "This regulates the planning objectives, competencies, timetable for the next steps in the procedure, involvement and information of the communalities, and the procedure for adapting the cantonal planning.",
      "gist": "The agreement defines planning goals, responsibilities, schedule, community involvement, information sharing, and cantonal planning adaptation process."
    }
  ]
}
